  shell: {design_id: PWMA, clock: clk_sys, reset: rst_sys}
  modules:
    - name: c12_nexys_pwm_audio_top
      kind: rtl
      clocks: {clk: clk_sys}
      resets: {rst: rst_sys}
      params: {CLKS_PER_BIT: 868, TIMEOUT_CYCLES: 100000000, BUILD_STAMP: 0}
    - name: audio_state
      kind: rtl
      clocks: {clk: clk_sys}
      resets: {rst: rst_sys}
      window_base: 0x00
    - name: pwm_stage
      kind: rtl
      clocks: {clk: clk_sys}
      resets: {rst: rst_sys}
  connections: []
  board_ports:
    - {name: CLK100MHZ, dir: in, drive: input, to: clk_sys}
    - {name: CPU_RESETN, dir: in, drive: input, to: rst_sys}
    - {name: UART_TXD_IN, dir: in, drive: input, to: c12_nexys_pwm_audio_top.uart_rx}
    - {name: UART_RXD_OUT, dir: out, drive: push-pull, from: c12_nexys_pwm_audio_top.uart_tx}
    - {name: AUD_PWM, dir: out, drive: pulled-up, from: c12_nexys_pwm_audio_top.aud_pwm}
    - {name: AUD_SD, dir: out, drive: push-pull, from: c12_nexys_pwm_audio_top.aud_sd}
