  owned: []
  assumptions:
    - {id: A-1, text: "Choose the default CLKS_PER_BIT for the 100 MHz shell clock and 115200 baud.", default: "868 clock cycles per bit", reason: "The specification gives the clock and baud rate but not the parameter default; 100000000 / 115200 rounds to 868.", affects: [c12_nexys_pwm_audio_top.contract.parameters.CLKS_PER_BIT], status: open}
