    data_formats: []
  audio_state:
    schema: fpga-design-agent/contract/v1
    module: audio_state
    summary: Holds the signed sample and capped unsigned Q15 gain, and computes sample_out combinationally.
    clocks:
      - {name: clk, port: clk, max_mhz: 100}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_low, style: async}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: sample, dir: in, width: 16, clock: clk, reset_value: 0}
      - {name: gain, dir: in, width: 16, clock: clk, reset_value: 2068}
      - {name: sample_out, dir: out, width: 16, clock: clk}
