      - {name: sample_s16, format: s16, packing: "signed 16-bit audio sample"}
      - {name: gain_u16, format: u16, packing: "unsigned Q15 gain register"}
      - {name: sample_out_s16, format: s16, packing: "signed 16-bit result"}
